<template><div class="tenant-card"><div class="head"><h3>收藏房源</h3><router-link to="/properties">继续找房</router-link></div><div v-if="rows.length" class="property-grid"><div v-for="item in rows" :key="item.favorite_id" class="property-card"><img :src="cover(item)" alt=""><div class="p"><strong>{{ item.title }}</strong><p>{{ item.district }} · {{ item.address }}</p><div class="price">¥{{ Number(item.price || 0).toLocaleString() }}/月</div><div class="actions"><router-link :to="`/properties/${item.id}`">查看详情</router-link><button @click="remove(item.id)">取消收藏</button></div></div></div></div><div v-else class="empty-state">暂无收藏房源。</div></div></template>
<script setup>import { onMounted, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { tenantApi } from '@/api/modules/tenant'; const rows=ref([]); async function load(){rows.value=(await tenantApi.getFavorites()).data||[]} function cover(item){const imgs=Array.isArray(item.images)?item.images:[]; return imgs[0] || '/images/placeholder-property.jpg'} async function remove(id){await tenantApi.removeFavorite(id); ElMessage.success('已取消收藏'); load()} onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.head h3{font-size:16px;margin:0}.head a{color:#0f766e;text-decoration:none}.property-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.property-card{border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;background:#fff}.property-card img{width:100%;height:150px;object-fit:cover;background:#f1f5f9}.p{padding:12px}.p p{color:#64748b;font-size:13px;margin:6px 0}.price{color:#dc2626;font-weight:800}.actions{display:flex;justify-content:space-between;margin-top:10px}.actions a,.actions button{border:0;background:transparent;color:#0f766e;font-size:13px;text-decoration:none;padding:0}@media(max-width:900px){.property-grid{grid-template-columns:1fr}}</style>
